WHY = ('Цена эпизода госпитализации (DRG) не должна сливаться в один диапазон с амбулаторной ценой той же процедуры у КЦЦГ, '
       'либо процедура в каталоге совпадает неточно — отдельная запись по конвенции hospitalization-for-*.')
o = json.load(open('match/overrides.json', encoding='utf-8'))
